      cwd: dir,
      encoding: "utf8",
      env: { ...process.env, BRIDGE_EXIT: String(code) },
    });
  return { dir, task, run };
}

test("the standalone launcher passes one literal task, preserves evidence and resumes the supplied session", () => {
  const { dir, run } = fixture();
