// The hub on this machine: its database, the view kept from the log, the rules file, and one way to apply an input.
// Importing this opens them all, which is why the checks that must survive a bad rules file import it late.
import { randomBytes } from "node:crypto";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { DatabaseSync, type SQLInputValue } from "node:sqlite";
import { HOME, RULES_FILE } from "./home.ts";
import { privateDirectory } from "./files.ts";
import { stateOf as state, viewStatements } from "./state.ts";
import { cardHash, digest, whose as keyHolder } from "../kernel/credentials.ts";
import { decide } from "../kernel/decide.ts";
import { NotFound } from "../kernel/errors.ts";
import { initialize, rows, statement, type Fact, type Row, type Table } from "../kernel/evolve.ts";
import * as query from "../kernel/query.ts";
import { commitLatest, openView } from "../kernel/store.ts";
import { parseRules as checkRules, RulesError } from "../protocol/rules.ts";

privateDirectory(HOME);
const masterKeyFile = join(HOME, "master.key");
if (!existsSync(masterKeyFile)) {
  writeFileSync(masterKeyFile, randomBytes(32).toString("base64url"), { mode: 0o600, flag: "wx" });
}
const masterKey = readFileSync(masterKeyFile, "utf8").trim();
// An empty or cut-short key would still sign links, and card links derive from what channels see. Replacing it would
// void every link and token, so that is left to the owner.
if (!/^[A-Za-z0-9_-]{43}$/.test(masterKey)) {
  throw new Error(
    `${masterKeyFile} 坏了（应该是 43 个字符），中台不启动。从备份恢复这个文件；没有备份就删掉它，` +
      "重启会生成新的，但已经发出的卡片链接和正在跑的轮次会失效。",
  );
}
export const environment = {
  secret: masterKey,
  publicUrl: process.env.AGENT_AUTOLOOP_PUBLIC_URL ?? "",
};

export const db = new DatabaseSync(join(HOME, "hub.db"));
db.exec("PRAGMA journal_mode=WAL; PRAGMA synchronous=FULL; PRAGMA busy_timeout=5000;");
db.function("card_hash", { deterministic: true }, (id, at) => cardHash(environment, id, at));
initialize(db);

// Other processes must see either the old views or the new ones, never the gap between DROP and CREATE.
db.exec(`BEGIN IMMEDIATE; ${viewStatements.join(";")}; COMMIT`);

const CARD_HASH_INDEX =
  "CREATE INDEX IF NOT EXISTS projection_card_hash ON projections(card_hash(json_extract(data,'$.id'),json_extract(data,'$.created_at'))) WHERE collection='cards'";

// The persisted projection is expendable; the log alone rebuilds it, which an upgrade has to wait for. So only the files that
// decide what's stored count here, whole, since what they do is spread across helpers and constants. The views above are
// made anew at every start and need no rebuild.
const format = digest(
  ["../kernel/evolve.ts", "../kernel/credentials.ts"]
    .map((file) => readFileSync(new URL(file, import.meta.url), "utf8"))
    .join("\n") +
    CARD_HASH_INDEX +
    digest(environment.secret),
);
let current = openView(db, format);
db.exec(CARD_HASH_INDEX);

export const all = <T>(sql: string, params: SQLInputValue[] = []) =>
  db
    .prepare(sql)
    .all(...params)
    .map((row) => ({ ...row }) as T);

export const one = <T>(sql: string, params: SQLInputValue[] = []) => {
  const row = db.prepare(sql).get(...params);
  return row ? ({ ...row } as T) : undefined;
};

export function getView() {
  current = openView(db, format);
  return current;
}

type Listener = (type: string, facts: Fact[]) => void;
const listeners = new Set<Listener>();

export const onChange = (listener: Listener) => {
  listeners.add(listener);
  return () => listeners.delete(listener);
};

export function execute(type: string, args: any[], now = Date.now()) {
  let facts: Fact[] = [];
  let value: any;
  current = commitLatest(db, format, (latest) => {
    ({ facts, value } = decide(latest, { type, args }, now, environment));
    return facts;
  });
  if (facts.length) for (const listener of listeners) listener(type, facts);
  return value;
}

export const parseRules = (json: string, now = Date.now()) =>
  checkRules(json, now, Intl.DateTimeFormat().resolvedOptions().timeZone);
export let rules = query.configuration(current);

export function reloadRules(file = RULES_FILE): { problem?: string } {
  let text: string;
  try {
    text = readFileSync(file, "utf8");
  } catch (error) {
    return { problem: unreadable(file, error as NodeJS.ErrnoException) };
  }
  try {
    const next = parseRules(text);
    const differs = JSON.stringify(next) !== JSON.stringify(query.configuration(getView()));
    const reportedBroken = (card: Row) => card.key.startsWith("rules:") && card.state === "open";
    if (differs || rows(current, "cards", { state: "open" }).some(reportedBroken)) execute("rules", [next]);
    rules = next;
    return {};
  } catch (error) {
    if (error instanceof RulesError) return { problem: error.message };
    throw error;
  }
}

function unreadable(file: string, error: NodeJS.ErrnoException) {
  if (error.code === "ENOENT") return `找不到 ${file}，被删掉或移走了？放回去就会接着用`;
  if (error.code === "EACCES" || error.code === "EPERM") return `没有权限读 ${file}，改回能读的权限就会接着用`;
  return `读不到 ${file}：${error.code ?? error.message}`;
}

const initial = reloadRules();
if (!rules) throw new Error(initial.problem ?? "缺少规则");

let toldOf: string | undefined;

export function tick(now = Date.now()) {
  const { problem } = reloadRules();
  // A file still gone or still wrong is a problem at every tick, and an owner who closed the card has heard.
  if (problem && problem !== toldOf) execute("rulesError", [problem], now);
  toldOf = problem;
  execute("tick", [], now);
}

export function cardByToken(token: string) {
  const row = statement(
    db,
    "SELECT data FROM projections WHERE collection='cards' AND card_hash(json_extract(data,'$.id'),json_extract(data,'$.created_at'))=?",
  ).get(digest(token));
  return row ? (JSON.parse(String(row.data)) as Row) : undefined;
}

export const view = (card: Row, ref: string | null = null, links = false) =>
  query.cardView(card, environment, ref, links);
export const unrouted = (limit = 20) => query.unrouted(getView(), limit);
/** Read in one snapshot: its seq is where the log stood for all of it, for a client to go on in /v1/stream from. */
export function stateOf(now = Date.now(), before?: number) {
  db.exec("BEGIN");
  try {
    const latest = getView();
    return { seq: latest.seq, ...state(now, before, query.configuration(latest), { all, view, unrouted }) };
  } finally {
    db.exec("COMMIT");
  }
}

export type KeyKind = "source" | "worker" | "channel" | "owner";
export const keepKeyHash = (kind: KeyKind, name: string, hash: string, now = Date.now()) =>
  execute("key", [kind, name, hash], now);

export function addKey(kind: KeyKind, name: string, now = Date.now()) {
  const key = randomBytes(32).toString("base64url");
  keepKeyHash(kind, name, digest(key), now);
  return key;
}

export const listKeys = () =>
  all<{ kind: string; name: string; created_at: string }>("SELECT kind,name,created_at FROM keys ORDER BY kind,name");
export const whose = (kind: string, key: string) => keyHolder(getView(), kind, key);
export const logAfter = (after = 0, limit = -1) =>
  db
    .prepare("SELECT fact FROM facts WHERE seq > ? ORDER BY seq LIMIT ?")
    .all(after, limit)
    .map((row) => query.safeFact(JSON.parse(String(row.fact))));

/** The part of the log that explains one run: its events, cards and receipts, and the rules it ran under. */
export function why(id: number) {
  const latest = getView();
  if (!latest.get("runs", id)) throw new NotFound("没有这一轮");
  const events = query.eventsOf(latest, id).map((event) => event.id);
  const cards = [...rows(latest, "cards", { run_id: id }), ...rows(latest, "cards", { answer_event: events })];
  const sequences = new Set<number>();
  const include = (table: Table, key: string | number) => {
    for (const row of statement(db, "SELECT seq FROM projection_refs WHERE collection=? AND key=?").all(
      table,
      String(key),
    ))
      sequences.add(Number(row.seq));
  };
  include("runs", id);
  const read = (seq: number): Fact =>
    JSON.parse(String(statement(db, "SELECT fact FROM facts WHERE seq=?").get(seq)!.fact));
  for (const seq of [...sequences])
    for (const change of read(seq).changes)
      if (change.table === "runs" && change.key === String(id) && change.row?.rules_version)
        sequences.add(change.row.rules_version);
  for (const event of events) include("events", event);
  for (const card of cards) include("cards", card.id);
  return [...sequences].sort((a, b) => a - b).map((seq) => query.safeFact(read(seq)));
}

// What the kernel's doors need from this machine: the clock, a timer for the next deadline, long polls to wake, the
// rules file to watch, the log as a stream and the webhook plugins.
import { realpathSync, watch } from "node:fs";
import { basename, dirname } from "node:path";
import { RULES_FILE } from "./home.ts";
import { loadPlugin } from "./plugins.ts";
import * as hub from "./runtime.ts";
import { AuthError, NotFound } from "../kernel/errors.ts";
import { createHandler } from "../kernel/http.ts";

/** Past this setTimeout fires at once. */
const LONGEST_TIMER = 2147483647;
const TICK_RETRY = 5_000;

function logStream(after: number, signal: AbortSignal, key: string) {
  let position = after;
  let unsubscribe = () => {};
  let stop = () => {};
  const detach = () => {
    unsubscribe();
    signal.removeEventListener("abort", stop);
  };
  let send = () => {};
  let stopped = false;
  return new ReadableStream({
    start(controller) {
      stop = () => {
        if (stopped) return;
        stopped = true;
        detach();
        controller.close();
      };
      send = () => {
        if (stopped) return;
        if (!hub.whose("owner", key)) return stop();
        if (controller.desiredSize! <= 0) return;
        for (const fact of hub.logAfter(position, 1)) {
          position = fact.seq;
          const message = `id: ${fact.seq}\nevent: fact\ndata: ${JSON.stringify(fact)}\n\n`;
          controller.enqueue(new TextEncoder().encode(message));
        }
      };
      unsubscribe = hub.onChange(send);
      signal.addEventListener("abort", stop, { once: true });
      if (signal.aborted) stop();
    },
    pull() {
      send();
    },
    cancel() {
      stopped = true;
      detach();
    },
  });
}

async function adaptWebhook(source: string, headers: Headers, body: string) {
  const adapter = hub.rules.sources[source]?.adapter;
  if (!adapter || !/^[a-z][a-z0-9-]*$/.test(adapter)) throw new NotFound("这个来源不收 Webhook");
  const translate = await loadPlugin(adapter, "source");
  const secret = [REDACTED]"-", "_")}`] ?? "";
  try {
    const events = translate({ headers: Object.fromEntries(headers), body, secret });
    return Array.isArray(events) ? events : [];
  } catch {
    throw new AuthError("验签没过");
  }
}

export function makeHandler(commit = "dev") {
  let timer: NodeJS.Timeout | undefined;
  let closed = false;
  let retryAt: number | undefined;
  const waiting = new Set<{ until: number; done: () => void }>();
  const wake = () => {
    for (const waiter of [...waiting]) waiter.done();
  };
  const fire = () => {
    try {
      hub.tick();
      retryAt = undefined;
    } catch (error) {
      // Another process holding the database too long, say. Nobody is there to catch it, and what it brought is still due.
      console.error(error);
      retryAt = Date.now() + TICK_RETRY;
    }
    wake();
    arm();
  };
  const arm = () => {
    clearTimeout(timer);
    if (closed) return;
    const due = hub.one<{ at: number }>(
      "SELECT MIN(json_extract(data, '$.at')) AS at FROM projections WHERE collection='due'",
    );
    // Whatever the failed tick left is overdue, so it would go at once; and nothing else coming along may lose the retry.
    const next = retryAt ?? Math.min(due?.at ?? Infinity, ...[...waiting].map((waiter) => waiter.until));
    if (!Number.isFinite(next)) return;
    timer = setTimeout(fire, Math.max(0, Math.min(LONGEST_TIMER, next - Date.now())));
  };
  const unlisten = hub.onChange((type, facts) => {
    // Being seen wakes nobody, unless it changed a card.
    const justSeen = type === "heartbeat" || type === "channelSeen";
    if (!justSeen || facts.some((fact) => fact.changes.some((change) => change.table === "cards"))) wake();
    arm();
  });
  // libuv 1.52 (Node 24.16+) on Windows asserts and exits on the first change in a folder named through an 8.3 short name.
  const watcher = watch(realpathSync.native(dirname(RULES_FILE)), (_event, file) => {
    if (file === basename(RULES_FILE)) fire();
  });
  const handle = createHandler({
    commit,
    now: Date.now,
    view: hub.getView,
    environment: hub.environment,
    dispatch: hub.execute,
    state: hub.stateOf,
    why: hub.why,
    card: hub.cardByToken,
    wait(until, signal) {
      return new Promise((resolve) => {
        const waiter = {
          until,
          done() {
            waiting.delete(waiter);
            signal.removeEventListener("abort", waiter.done);
            resolve();
          },
        };
        waiting.add(waiter);
        signal.addEventListener("abort", waiter.done, { once: true });
        if (signal.aborted) waiter.done();
        arm();
      });
    },
    stream: logStream,
    adapt: adaptWebhook,
  });
  fire();
  return {
    handle,
    close() {
      closed = true;
      clearTimeout(timer);
      watcher.close();
      unlisten();
      wake();
    },
  };
}

// Run tokens and card links derive from the master key, so they're never stored. Access keys are kept only as hashes.
import { createHash, createHmac, timingSafeEqual } from "node:crypto";
import { rows, type View } from "./evolve.ts";

export type Environment = { secret: string; publicUrl: string };

export const digest = (text: string) => createHash("sha256").update(text).digest("hex");

export const credential = (env: Environment, purpose: string, ...parts: unknown[]) =>
  createHmac("sha256", env.secret)
    .update(JSON.stringify([purpose, ...parts]))
    .digest("base64url");

/** What a card is found by from its link, which isn't stored. */
export const cardHash = (env: Environment, id: unknown, at: unknown) => digest(credential(env, "card", id, at));

export function whose(view: View, kind: string, key: string): string | null {
  if (!key) return null;
  const given = Buffer.from(digest(key), "hex");
  const found = rows(view, "keys").find(
    (row) => row.kind === kind && timingSafeEqual(Buffer.from(row.hash, "hex"), given),
  );
  return found?.name ?? null;
}

// A hub, from the outside: how a worker, a channel or the command line reaches it. Nothing here is more than an HTTP
// request, which is the whole of what it takes to plug into the hub.
export class HubError extends Error {
  readonly status: number;
  constructor(status: number, message: string) {
    super(message);
    this.status = status;
  }
}

export function hubClient(url: string, key: string) {
  const base = url.replace(/\/$/, "");
  async function call(
    method: string,
    path: string,
    { token = key, body, timeout = 30 }: { token?: string; body?: unknown; timeout?: number } = {},
  ) {
    const response = await fetch(base + path, {
      method,
      headers: { authorization: `Bearer ${token}`, ...(body !== undefined && { "content-type": "application/json" }) },
      ...(body !== undefined && { body: JSON.stringify(body) }),
      signal: AbortSignal.timeout(timeout * 1000),
    });
    const text = await response.text();
    let data: any = null;
    try {
      data = text ? JSON.parse(text) : null;
    } catch {}
    if (!response.ok) throw new HubError(response.status, data?.error ?? `中台返回 ${response.status}`);
    return data;
  }
  return {
    // The worker's door.
    work({ claim, wait, running, capacity }: { claim: string; wait: number; running: number[]; capacity: boolean }) {
      const query = { claim, wait: String(wait), running: running.join(","), capacity: capacity ? "1" : "0" };
      return call("GET", `/v1/work?${new URLSearchParams(query)}`, { timeout: wait + 30 });
    },
    started: (run: number, token: string, body: { session?: string; link?: string }) =>
      call("POST", `/v1/runs/${run}/started`, { token, body }),
    result: (run: number, token: string, body: unknown) => call("POST", `/v1/runs/${run}/result`, { token, body }),
    // The channel's door.
    nextCard: (wait: number) => call("GET", `/v1/cards/next?wait=${wait}`, { timeout: wait + 30 }),
    delivered: (card: number, version: number, ref: string | null) =>
      call("POST", `/v1/cards/${card}/delivered`, { body: { version, ref } }),
    failed: (card: number, version: number, error: string) =>
      call("POST", `/v1/cards/${card}/failed`, { body: { version, error } }),
    answer: (card: number, body: { choice?: number; text?: string; by?: string; ref?: string }) =>
      call("POST", `/v1/cards/${card}/answer`, { body }),
    // Sources, the owner and tasks elsewhere.
    event: (body: unknown) => call("POST", "/v1/events", { body }),
    tell: (body: unknown) => call("POST", "/v1/tell", { body }),
    why: (id: number) => call("GET", `/v1/runs/${id}/why`),
    removeKey: (kind: string, name: string) =>
      call("DELETE", `/v1/keys/${encodeURIComponent(kind)}/${encodeURIComponent(name)}`),
    state: (before?: number) => call("GET", before === undefined ? "/v1/state" : `/v1/state?before=${before}`),
    cancel: (run: number) => call("POST", `/v1/runs/${run}/cancel`, { body: {} }),
    resolve: (card: number, reason: string) => call("POST", `/v1/cards/${card}/resolve`, { body: { reason } }),
    // Rule control: facts in the log, rules.json stays as the owner wrote it.
    pause: (rule: string, body: { reason?: string; until?: string } = {}) =>
      call("POST", `/v1/rules/${encodeURIComponent(rule)}/pause`, { body }),
    resume: (rule: string) => call("POST", `/v1/rules/${encodeURIComponent(rule)}/resume`, { body: {} }),
    run: (rule: string, body: { subject?: string; reason?: string } = {}) =>
      call("POST", `/v1/rules/${encodeURIComponent(rule)}/run`, { body }),
  };
}
export type Hub = ReturnType<typeof hubClient>;

