// JSON Schema, as much of it as protocol/schema.json uses, so checking the protocol needs nothing installed.
import { readFileSync } from "node:fs";
import { dateTime } from "./validate.ts";

export const schemas = JSON.parse(readFileSync(new URL("./schema.json", import.meta.url), "utf8"));

function hasType(type: string, item: unknown) {
  if (type === "object") return item !== null && typeof item === "object" && !Array.isArray(item);
  if (type === "array") return Array.isArray(item);
  if (type === "integer") return Number.isSafeInteger(item);
  if (type === "null") return item === null;
  return typeof item === type;
}

const outside = (value: number, min?: number, max?: number) =>
  (min !== undefined && value < min) || (max !== undefined && value > max);

function visit(schema: any, item: any, path: string): string[] {
  const passes = (option: any) => visit(option, item, path).length === 0;
  if (schema.$ref) return visit(schemas.$defs[schema.$ref.split("/").at(-1)], item, path);
  if (schema.anyOf && !schema.anyOf.some(passes)) return [path];
  if (schema.oneOf && schema.oneOf.filter(passes).length !== 1) return [path];
  if (schema.const !== undefined && item !== schema.const) return [path];
  if (schema.enum && !schema.enum.includes(item)) return [path];
  const types: string[] = Array.isArray(schema.type) ? schema.type : [schema.type];
  if (schema.type && !types.some((type) => hasType(type, item))) return [path];
  if (typeof item === "string") {
    if (outside([...item].length, schema.minLength, schema.maxLength)) return [path];
    if (schema.pattern && !new RegExp(schema.pattern, "u").test(item)) return [path];
  }
  if (schema.format === "date-time" && !dateTime(item)) return [path];
  if (typeof item === "number") {
    if (!Number.isFinite(item) || outside(item, schema.minimum, schema.maximum)) return [path];
  }
  if (Array.isArray(item)) {
    if (outside(item.length, schema.minItems, schema.maxItems)) return [path];
    return item.flatMap((child, index) => (schema.items ? visit(schema.items, child, `${path}[${index}]`) : []));
  }
  if (item === null || typeof item !== "object") return [];
  const required: string[] = schema.required ?? [];
  const errors = required.filter((key) => !Object.hasOwn(item, key)).map((key) => `${path}.${key}`);
  for (const [key, child] of Object.entries(item)) {
    const known = Object.hasOwn(schema.properties ?? {}, key) ? schema.properties[key] : undefined;
    const childPath = `${path}.${key}`;
    if (known) errors.push(...visit(known, child, childPath));
    else if (schema.additionalProperties === false) errors.push(childPath);
    else if (typeof schema.additionalProperties === "object") {
      errors.push(...visit(schema.additionalProperties, child, childPath));
    }
  }
  return errors;
}

export function checkSchema(name: string, value: unknown): string[] {
  if (!Object.hasOwn(schemas.$defs, name)) throw new Error(`没有这个协议类型：${name}`);
  return visit(schemas.$defs[name], value, name);
}

// The smallest channel: every card becomes a few lines in a file. Someone answers with `agent-autoloop answer`, because a file
// has no buttons.
//   rules.json:  "channels": { "cards": { "name": "文件" } }
//   config.json: "channels": { "cards": { "use": "hello-channel", "key": "…", "file": "/绝对路径/cards.txt" } }
import { appendFileSync } from "node:fs";

type Card = { id: number; version: number; ref: string | null; title: string; text: string; options: string[] };
type Context = {
  hub: {
    nextCard(wait: number): Promise<{ card: Card | null }>;
    delivered(card: number, version: number, ref: string | null): Promise<unknown>;
    failed(card: number, version: number, error: string): Promise<unknown>;
  };
  options: Record<string, unknown>;
  log: (line: string) => void;
  signal: AbortSignal;
};

const words = ({ id, title, text, options }: Card) =>
  [`#${id} ${title}`, text, ...options.map((option, index) => `  ${index + 1}. ${option}`), ""].join("\n");

export default async function helloChannel({ hub, options, log, signal }: Context) {
  while (!signal.aborted) {
    const { card } = await hub.nextCard(50);
    if (!card) continue;
    // A card with a ref has changed since it went out. A file can't change what it said, so there's only the report.
    if (card.ref) {
      await hub.delivered(card.id, card.version, card.ref);
      continue;
    }
    try {
      appendFileSync(options.file as string, words(card));
      await hub.delivered(card.id, card.version, `file-${card.id}`);
    } catch (error) {
      log(`card ${card.id} not written: ${error}`);
      await hub.failed(card.id, card.version, String(error));
    }
  }
}

// The smallest webhook plugin, for a made-up system that POSTs { "id", "kind", "order", "note" } and signs the body with
// HMAC-SHA256 in the x-shop-signature header. It only translates: it makes no requests, and it can't be async.
//   rules.json:  "sources": { "shop": { "name": "shop", "adapter": "hello-source" } }
//   secrets.env: AGENT_AUTOLOOP_SECRET_SHOP=…
// The address to give the other side is /v1/in/shop.
import { createHmac, timingSafeEqual } from "node:crypto";

type Input = { headers: Record<string, string | string[] | undefined>; body: string; secret: string };

export default function helloSource({ headers, body, secret }: Input) {
  const expected = Buffer.from(`sha256=${createHmac("sha256", secret).update(body).digest("hex")}`);
  const given = Buffer.from(String(headers["x-shop-signature"] ?? ""));
  if (!secret || given.length !== expected.length || !timingSafeEqual(given, expected)) throw new Error("signature");
  const { id, kind, order, note } = JSON.parse(body);
  if (kind === "ping") return [];
  return [
    { id: String(id), type: `order.${kind}`, subject: `order-${order}`, summary: String(note ?? "").slice(0, 200) },
  ];
}
